using System;using System.Collections.Generic;using System.Linq;using System.Runtime.InteropServices;using System.Threading;
namespace DesktopBox {
public static partial class ControlWifi {
 [StructLayout(LayoutKind.Sequential)]struct Notification {public uint Source,Code;public Guid Interface;public uint Size;public IntPtr Data;}
 [UnmanagedFunctionPointer(CallingConvention.Winapi)]delegate void NotificationCallback(ref Notification data,IntPtr context);
 [DllImport("wlanapi.dll")]static extern uint WlanRegisterNotification(IntPtr handle,uint source,[MarshalAs(UnmanagedType.Bool)]bool ignoreDuplicate,NotificationCallback callback,IntPtr context,IntPtr reserved,out uint previous);
 [DllImport("wlanapi.dll")]static extern uint WlanScan(IntPtr handle,ref Guid id,IntPtr ssid,IntPtr informationElements,IntPtr reserved);
 public sealed class AdapterScan {public Guid Id;public bool Requested,Finished,Completed;public uint RequestCode,FailureReason;public string Error="";}
 public sealed class ScanReport {public string Started,Finished,Warning="",ReadError="";public long ElapsedMs;public bool Fresh;public int BeforeCount,AfterCount;public List<AdapterScan> Adapters=new List<AdapterScan>();}
 static readonly object scanGate=new object();public static ScanReport LastScan;
 public static List<Available> DistinctNetworks(IEnumerable<Available> networks){return networks.GroupBy(n=>BitConverter.ToString(n.SsidBytes??System.Text.Encoding.UTF8.GetBytes(n.Name??""))+"|"+n.Secured+"|"+n.Auth+"|"+n.Cipher+"|"+n.Bss).Select(g=>g.OrderByDescending(n=>n.Connected).ThenByDescending(n=>n.Signal).First()).OrderByDescending(n=>n.Connected).ThenByDescending(n=>n.Signal).ThenBy(n=>n.Name,StringComparer.CurrentCulture).ToList();}
 public static List<Available> ScanAndList(){lock(scanGate){var report=new ScanReport{Started=DateTimeOffset.Now.ToString("o")};var clock=System.Diagnostics.Stopwatch.StartNew();report.BeforeCount=List().Count;IntPtr handle=IntPtr.Zero,list=IntPtr.Zero;NotificationCallback callback=null;bool registered=false;object gate=new object();using(var done=new ManualResetEvent(false)){try{uint version,error=WlanOpenHandle(2,IntPtr.Zero,out version,out handle);if(error!=0)throw new System.ComponentModel.Win32Exception((int)error);error=WlanEnumInterfaces(handle,IntPtr.Zero,out list);if(error!=0)throw new System.ComponentModel.Win32Exception((int)error);int count=Marshal.ReadInt32(list);if(count<0||count>64)throw new InvalidOperationException("无线接口列表无效");for(int index=0;index<count;index++){var adapter=(Interface)Marshal.PtrToStructure(IntPtr.Add(list,8+index*Marshal.SizeOf(typeof(Interface))),typeof(Interface));if(adapter.State!=0)report.Adapters.Add(new AdapterScan{Id=adapter.Id});}if(report.Adapters.Count==0)throw new InvalidOperationException("未发现可用无线网卡，请确认Wi-Fi已开启");
   callback=(ref Notification notification,IntPtr context)=>{try{if((notification.Source&8)==0||(notification.Code!=7&&notification.Code!=8))return;lock(gate){Guid id=notification.Interface;var adapter=report.Adapters.FirstOrDefault(a=>a.Id==id);if(adapter==null||!adapter.Requested||adapter.Finished)return;adapter.Finished=true;adapter.Completed=notification.Code==7;if(!adapter.Completed){if(notification.Data!=IntPtr.Zero&&notification.Size>=4)adapter.FailureReason=unchecked((uint)Marshal.ReadInt32(notification.Data));adapter.Error="网卡扫描失败（原因 "+adapter.FailureReason+"）";}if(report.Adapters.All(a=>a.Finished))done.Set();}}catch{}};
   uint previous;error=WlanRegisterNotification(handle,8,false,callback,IntPtr.Zero,IntPtr.Zero,out previous);if(error!=0)throw new System.ComponentModel.Win32Exception((int)error);registered=true;
   foreach(var adapter in report.Adapters){lock(gate)adapter.Requested=true;Guid id=adapter.Id;error=WlanScan(handle,ref id,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero);lock(gate){adapter.RequestCode=error;if(error!=0){adapter.Finished=true;adapter.Completed=false;adapter.Error="无法启动扫描："+new System.ComponentModel.Win32Exception((int)error).Message;}if(report.Adapters.All(a=>a.Finished))done.Set();}}
   done.WaitOne(10000);lock(gate){foreach(var adapter in report.Adapters.Where(a=>!a.Finished)){adapter.Finished=true;adapter.Error="扫描未在等待时间内完成";}report.Fresh=report.Adapters.All(a=>a.Completed);report.Warning=String.Join("；",report.Adapters.Where(a=>!String.IsNullOrEmpty(a.Error)).Select(a=>a.Error));}
  }catch(Exception ex){report.Warning="无法完成无线扫描："+ex.Message;}finally{if(registered){uint previous;WlanRegisterNotification(handle,0,false,null,IntPtr.Zero,IntPtr.Zero,out previous);}if(list!=IntPtr.Zero)WlanFreeMemory(list);if(handle!=IntPtr.Zero)WlanCloseHandle(handle,IntPtr.Zero);GC.KeepAlive(callback);}}
  var result=List();report.ReadError=LastError;report.AfterCount=result.Count;if(report.ReadError!="")report.Fresh=false;report.Warning=String.Join("；",new[]{report.Warning,report.ReadError}.Where(x=>!String.IsNullOrEmpty(x)));LastError=report.Warning;report.Finished=DateTimeOffset.Now.ToString("o");report.ElapsedMs=clock.ElapsedMilliseconds;LastScan=report;try{System.IO.File.WriteAllText(System.IO.Path.Combine(Program.S.Root,"wifi-scan-state.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{report,networks=result.Select(n=>new{n.Name,n.Signal,n.Connected,n.Auth,n.Cipher,n.Interface}).ToArray(),scope="实际WlanScan请求、ACM完成/失败通知，然后读取系统网络列表；不连接、断开、修改无线或位置设置，不记录密码"}),System.Text.Encoding.UTF8);}catch{}return result;
 }}
}
}
